import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 44 Speed and comfort","description":"学习 平行结构与 not only，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 44 Speed and comfort","description":"学习 平行结构与 not only，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 平行结构与 not only，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 43 Fully insured","link":"/life/english/new-concept/book-3/unit-03/lesson-043"},"next":{"text":"第三册：培养技能 · Lesson 45 The power of the press","link":"/life/english/new-concept/book-3/unit-03/lesson-045"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 43 Fully insured","link":"/life/english/new-concept/book-3/unit-03/lesson-043"},"next":{"text":"第三册：培养技能 · Lesson 45 The power of the press","link":"/life/english/new-concept/book-3/unit-03/lesson-045"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-044.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-044.md"}'),i={name:"life/english/new-concept/book-3/unit-03/lesson-044.md"};function l(r,e,s,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-44-speed-and-comfort" tabindex="-1">第三册：培养技能 · Lesson 44 Speed and comfort <a class="header-anchor" href="#第三册-培养技能-·-lesson-44-speed-and-comfort" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 44 Speed and comfort&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕出行方式选择练习权衡多个标准。速度、费用和舒适度可能指向不同方案，因此应先说明需求再比较。学习平行结构连接两个优点或限制，让读者清楚各项评价适用于同一个主语，同时避免形式对称却比较了不同性质的信息。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>comfort</td><td>/ˈkʌmfət/</td><td>n.</td><td>舒适</td><td>travel in comfort</td></tr><tr><td>efficient</td><td>/ɪˈfɪʃənt/</td><td>adj.</td><td>高效的</td><td>an efficient service</td></tr><tr><td>transfer</td><td>/ˈtrænsfɜː/</td><td>n.</td><td>换乘</td><td>a quick transfer</td></tr><tr><td>journey</td><td>/ˈdʒɜːni/</td><td>n.</td><td>旅程</td><td>a door-to-door journey</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take into consideration — 纳入考虑</li><li>door to door — 从出发门口到目的地门口</li></ul><h2 id="语法讲解-平行结构与-not-only" tabindex="-1">语法讲解：平行结构与 not only <a class="header-anchor" href="#语法讲解-平行结构与-not-only" aria-label="Permalink to &quot;语法讲解：平行结构与 not only&quot;">​</a></h2><p>and、or、both ... and、not only ... but also 连接的成分应尽量保持相同语法层次，如两个名词、两个形容词或两个分句。not only 置于句首并强调整个分句时，前半句通常部分倒装，后半句保持常规语序；若它只位于句中修饰两个宾语，则不需要倒装。平行结构提高可读性，但不能代替论证。比较交通时，还应把门到门时间和车上时间区分开，否则句式工整也可能得出误导性结论。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The night train offers both a quiet place to sleep and a direct route to the city centre.</p></blockquote><p>夜间列车既提供安静睡眠的地方，又提供直达市中心的路线。</p><p>both ... and 连接两个名词短语，均为 offers 的宾语，语法层级一致。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>both comfortable and saves time 不平行；可改为 both comfortable and convenient，或 It is comfortable and saves time。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 both 后第一个长短语时不要提前收尾，在 and 后保持同等语气，听出两项并列优点。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The express bus is faster on the main road. However, the local train takes me directly to the office district. It offers both predictable travel time and a seat where I can read.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>比较两种虚构通勤方案，用三句说明总时间和舒适度。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>局部速度与全程便利分开比较，两个优点以平行名词短语呈现。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句 both ... and 连接什么类型成分？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 两个名词短语。</p><p><strong>解析：</strong> a quiet place 与 a direct route 都是 offers 的宾语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>改写：The service is not only fast; it is also reliable.（Not only 开头）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Not only is the service fast, but it is also reliable.</p><p><strong>解析：</strong> 句首 not only 引发前半倒装。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>门到门时间是否只算车上时间？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> 还包括前往车站、换乘和到达目的地等环节。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：平行结构与 not only。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-043">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-045">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=t(i,[["render",l]]);export{u as __pageData,f as default};
